// Handle raw WhatsApp Cloud API webhook OR normalized sass-store format
const body = $json.body || $json;

// Try raw WhatsApp format first
let phone = null, msgBody = null, phoneNumberId = null, customerName = null, msgId = null;

const entry = body?.entry?.[0];
const change = entry?.changes?.[0]?.value;
if (change?.messages?.[0]) {
  const msg = change.messages[0];
  if (msg.type !== 'text') return []; // skip non-text messages
  phone = msg.from;
  msgBody = msg.text?.body || '';
  phoneNumberId = change.metadata?.phone_number_id;
  customerName = change.contacts?.[0]?.profile?.name || null;
  msgId = msg.id;
} else if (body?.message?.phone) {
  // Normalized sass-store format
  phone = body.message.phone;
  msgBody = body.message.content || body.message.body || '';
  phoneNumberId = body.phoneNumberId || '214863935038316';
  customerName = body.message.customerName || null;
  msgId = body.message.messageId || null;
} else {
  return []; // skip unknown format
}

if (!msgBody.trim()) return [];

return [{ json: { phone, msgBody, phoneNumberId, customerName, msgId } }];

const rows = $('Get Tenant + Services').all().map(i => i.json);
const cfg = rows[0] || {};
const services = rows.filter(r => r.service_name).map(r => r.service_name + ' ($' + r.price + ' MXN, ' + r.duration + 'min)').join(', ');
const msgBody = $('Parse WA Payload').item.json.msgBody;
const phone = $('Parse WA Payload').item.json.phone;
const customerName = $('Parse WA Payload').item.json.customerName;
const today = new Date().toLocaleDateString('es-MX', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'America/Mexico_City' });
const tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];
const todayIso = new Date().toISOString().split('T')[0];

const systemPrompt = 'Eres ' + (cfg.bot_name || 'Asistente') + ' de ' + (cfg.tenant_name || 'el salón') + '. Tono: ' + (cfg.tone || 'amigable y profesional') + '. Español mexicano. Responde SOLO con JSON válido sin markdown.\n\nServicios disponibles: ' + (services || 'manicure, pedicure, uñas gel, acrílico') + '\nFecha de hoy: ' + today + ' (' + todayIso + ')\nMañana: ' + tomorrow + '\n\nEstructura de respuesta OBLIGATORIA:\n{"intent":"AGENDAR|CONSULTAR|OTRO","service":"nombre o null","date":"YYYY-MM-DD o null","time":"HH:MM o null","clientName":"nombre o null","missing":["servicio","fecha","hora"],"reply":"respuesta amigable si OTRO, null si AGENDAR/CONSULTAR"}';

return [{
  json: {
    phone,
    customerName,
    tenantId: cfg.tenant_id,
    tenantSlug: cfg.tenant_slug,
    tenantName: cfg.tenant_name,
    phoneNumberId: cfg.phone_number_id || rows[0]?.phone_number_id,
    adminPhone: cfg.escalation_phone,
    systemPrompt,
    userMessage: msgBody
  }
}];

const aiResp = $('Call Ollama Cloud').item.json;
const ctx = $('Build Ollama Prompt').item.json;
const raw = aiResp?.choices?.[0]?.message?.content?.trim() || '{"intent":"OTRO","reply":"Hola, ¿en qué te puedo ayudar?"}';

let parsed;
try {
  // Remove markdown code blocks if present
  const clean = raw.replace(/```json?\s*/g,'').replace(/```/g,'').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { intent: 'OTRO', reply: 'Lo siento, no entendí bien. ¿Puedes repetirlo?' };
}

const missing = parsed.missing || [];
if (parsed.intent === 'AGENDAR') {
  if (!parsed.service) missing.push('el servicio que deseas');
  if (!parsed.date) missing.push('la fecha');
  if (!parsed.time) missing.push('la hora');
}

return [{
  json: {
    ...ctx,
    intent: parsed.intent || 'OTRO',
    service: parsed.service || null,
    date: parsed.date || null,
    time: parsed.time || null,
    clientName: parsed.clientName || ctx.customerName || null,
    missing: [...new Set(missing)],
    isComplete: parsed.intent === 'AGENDAR' && !!parsed.service && !!parsed.date && !!parsed.time,
    reply: parsed.reply || null
  }
}];

const citas = $('Obtener Citas Cliente').all().map(i => i.json);
const ctx = $('Parse Ollama Response').item.json;
let msg;
if (citas.length === 0) {
  msg = 'No tienes citas próximas agendadas 📅 ¿Quieres que te agende una?';
} else {
  const days = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
  const lista = citas.map(c => {
    const d = new Date(c.start_time);
    return '• ' + days[d.getDay()] + ' ' + d.toLocaleDateString('es-MX',{day:'2-digit',month:'short'}) + ' a las ' + d.toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit',hour12:true}) + ' — ' + c.service_name;
  }).join('\n');
  msg = 'Tus próximas citas 📅\n\n' + lista + '\n\n¿Necesitas algo más?';
}
return [{ json: { phone: ctx.phone, phoneNumberId: ctx.phoneNumberId, msg } }];
